mapper.update:
UPDATE wvp_platform
SET status = #{online}
WHERE server_gb_id = #{platformGbId}

mapper.select:
SELECT pp.*, ( (SELECT count(0) FROM wvp_platform_channel pc WHERE pc.platform_id = pp.id) + (SELECT count(0) FROM wvp_platform_group pg WHERE pg.platform_id = pp.id) * pp.catalog_with_group + (SELECT count(0) FROM wvp_platform_region pr WHERE pr.platform_id = pp.id) * pp.catalog_with_region + pp.catalog_with_platform ) as channel_count FROM wvp_platform pp WHERE 1=1
AND (pp.name LIKE CONCAT('%', #{query}, '%') ESCAPE '/' OR pp.server_gb_id LIKE CONCAT('%', #{query}, '%') ESCAPE '/')
ORDER BY pp.id DESC ${ew.customSqlSegment}
